import { get } from 'lodash'
import { withRouter } from 'react-router'
import { DisplayFlexCCC, Row } from '../../../../../../commonStyle/index.style'
import { Button, CustomText } from '../../../../../../components'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { formatMoney } from '../../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../../lang'
import { PkgCardStyle } from './index.style'

function PkgCard (props) {
  const { packageItem = {}, onSelectPkg } = props

  const renderPeriod = (period) => {
    return period === 12 ? `12 ${LANG_STRINGS.months}` : `${period} ${LANG_STRINGS.year}`
  }

  return (
    <PkgCardStyle>
      <Row className='pkg-name-box'>
        <DisplayFlexCCC className='package-img-box'>
          <img className='package-img' src={get(packageItem, 'provider.logo_url', '')} alt='package-logo' />
        </DisplayFlexCCC>
        <div>
          <CustomText color={AgentColorPallette.fontSecondary}>
            {get(packageItem, 'provider.name', '')}
          </CustomText>
          <CustomText color={AgentColorPallette.black} weight='800' size='14px'>
            {get(packageItem, 'package.name', '')}
          </CustomText>
        </div>
      </Row>
      <CustomText className='package-price' color={AgentColorPallette.mustard} weight='800' size='16px'>
        {formatMoney(get(packageItem, 'premium.amount', 0), 0)} / {renderPeriod(get(packageItem, 'premium.period', 0))}
      </CustomText>
      <CustomText
        size='11px'
        top='10px'
        bottom='4px'
        color={AgentColorPallette.fontDarkerGrey}
      >
        {LANG_STRINGS.valueOfCoverage} : <b>{formatMoney(packageItem.total_sum_insured, 0)}</b>
      </CustomText>
      <CustomText
        size='11px'
        color={AgentColorPallette.fontDarkerGrey}
        dangerouslySetInnerHTML={{
          __html: LANG_STRINGS.getPointsOnTransactions
            .replace('{commission}', formatMoney(packageItem.commission, 0))
            .replace('{points}', `${Math.floor(packageItem.points)} Poin`)
        }}
      />
      <Button
        onClick={onSelectPkg}
        className='pkg-select-btn'
        color={AgentColorPallette.darkerGold}
        id={`propertyPkgSelect-${packageItem.code}`}
      >
        {LANG_STRINGS.selectPkg}
      </Button>
    </PkgCardStyle>
  )
}

export default withRouter(PkgCard)
