import { useEffect, useMemo, useState } from 'react'
import { useHistory, useParams } from 'react-router'
import { connect } from 'react-redux'
import { Container } from '../../../../../components'
import StepsHeader from '../../../../../components/StepsHeader'
import { PKG_NOT_FOUND_PROPERTY } from '../../../../../images'
import policyActions from '../../../../../redux/policy/action'
import PkgNotFound from '../../../Application/components/PkgNotFound'
import { PolicyContextProvider } from '../../../Policy/context'
import { getPropPkgRequestData } from '../../helper'
import { PROPERTY_LANG } from '../../lang'
import PkgCard from '../components/PkgCard'
import useDraftApi from '../hooks/useDraftApi'
import { checkQuestionnaireAnswer } from '../constants'
import { PropertyPkgsStyle } from './index.style'

function PropertyPkgs ({ getPackages, packageList = {}, pkgLoading }) {
  const history = useHistory()
  const { draftId } = useParams()

  const [draftPolicyDetails, setDraftPolicyDetails] = useState({})
  const [selectedPackage, setSelectedPackage] = useState(null)
  const isPassQuestionnaire = useMemo(() => checkQuestionnaireAnswer(draftPolicyDetails.questionnaire), [draftPolicyDetails])

  const { isGetDraftLoader, isSaveLoader, handleSaveToDraft } = useDraftApi({
    draftId: draftId,
    onGetDraftDetailSuccess: (data) => {
      setDraftPolicyDetails(data.policy_details)
    },
    onSaveSuccess: ({ draftId }) => {
      history.push(`/property/property-protection/4/${selectedPackage?.code}/${draftId}`)
    }
  })

  useEffect(() => {
    if (Object.keys(draftPolicyDetails).length === 0) return

    const requestData = getPropPkgRequestData(draftPolicyDetails)
    if (!requestData) {
      history.replace('/property/property-protection/1/form')
      return
    }
    getPackages(requestData)
  }, [history, getPackages, draftPolicyDetails])

  const handleSelectPkg = (pkg) => {
    const updatedData = {
      ...draftPolicyDetails,
      provider_code: pkg.provider?.code,
      package_code: pkg.code,
      provider_package_code: pkg.code,
      code: pkg.code
    }
    setSelectedPackage(pkg)
    handleSaveToDraft(updatedData, 'package_details', 'package_details')
  }

  const propertyPkgs = [
    ...(packageList.complete_match || []),
    ...(packageList.no_match || []),
    ...(packageList.partial_match || [])
  ]
  const isPkgListLoading = pkgLoading || isGetDraftLoader
  const isNoData = !isPassQuestionnaire || (propertyPkgs?.length === 0 && !isPkgListLoading)

  return (
    <Container
      title={PROPERTY_LANG.propertyInsurance}
      loader={isPkgListLoading || isSaveLoader}
      hideBottomTabs
      showCloseIcon
      onClose={() => history.push('/dashboard')}
      onBackClick={() => history.push(`/property/property-protection/2/form/${draftId}`)}
    >
      <PropertyPkgsStyle>
        <StepsHeader
          current='3'
          totalSteps='6'
          leftText={PROPERTY_LANG.chooseInsurance}
          className='steps-header'
        />
        {
          !isNoData && (
            <div className='pkgs-container'>
              {propertyPkgs.map(pkg => (
                <PkgCard key={pkg.code} packageItem={pkg} onSelectPkg={() => handleSelectPkg(pkg)} />
              ))}
            </div>
          )
        }
        {
          isNoData && (
            <PkgNotFound
              history={history}
              image={PKG_NOT_FOUND_PROPERTY}
              msg={PROPERTY_LANG.pkgNotExist}
            />
          )
        }
      </PropertyPkgsStyle>
    </Container>
  )
}

function WrappedPropertyPkgs (props) {
  return (
    <PolicyContextProvider>
      <PropertyPkgs {...props} />
    </PolicyContextProvider>
  )
}

const { getPackages } = policyActions

export default connect(
  (state) => ({
    packageList: state.Policy.packages,
    pkgLoading: state.Loading.GET_PACKAGES
  }),
  {
    getPackages
  }
)(WrappedPropertyPkgs)
